export type GetResponses = {
    /**
     * Typed operation result
     */
    200: {
        data: {
            kind: 'billing';
            object: {
                organization: {
                    customerId: number;
                    name: string;
                };
                terms: {
                    requiredVersion: string;
                    url: string;
                    acceptedVersion: string | null;
                    acceptedAt: string | null;
                    currentVersionAccepted: boolean;
                    acceptanceRequired: boolean;
                    governedByExistingContract: boolean;
                    canAccept: boolean;
                };
                paymentAuthority: {
                    verified: boolean;
                    capture: {
                        /**
                         * `pending`: issued, not yet opened. `opened`: the hosted page exchanged the token at least once. `verified`: the card-rail webhook confirmed a payment method for this link. `expired`: the TTL elapsed before verification — terminal, never re-armed.
                         */
                        status: 'pending' | 'opened' | 'verified' | 'expired';
                        expiresAt: string;
                    } | null;
                    submission: {
                        /**
                         * Durable card-confirmation state. Only `verified` produces a usable payment authority; `processing`, `failed`, and `expired` are inert.
                         */
                        status: 'processing' | 'verified' | 'failed' | 'expired';
                        submittedAt: string;
                        completedAt: string | null;
                        failureReason: 'verification_failed' | 'canceled' | 'expired' | null;
                    } | null;
                    secureHandoff: {
                        available: false;
                        reason: 'secure_handoff_unavailable' | 'card_collection_not_enabled';
                    };
                };
                nextAction: {
                    type: 'ACCEPT_TOS' | 'ACCEPT_GOVERNING_AGREEMENT' | 'SELECT_IU_PLAN' | 'CONTACT_SCOPE3' | 'ADD_BILLING_INFO' | 'ADD_PAYMENT_METHOD' | 'FUND_PREPAY' | 'APPLY_FOR_CREDIT' | 'RESOLVE_HOLD' | 'UPDATE_PAYMENT_METHOD' | 'NONE';
                    /**
                     * Human sentence describing the action, for direct display.
                     */
                    message: string;
                    /**
                     * mintlify/v2 page explaining this action, when one exists.
                     */
                    docsUrl: string | null;
                    canCompleteInChat: boolean;
                };
            };
        } | {
            kind: 'account' | 'member' | 'agent' | 'buyer_agent' | 'skill' | 'inventory_source' | 'material' | 'wholesale_product' | 'advertiser' | 'advertiser_grant' | 'signal' | 'work_item' | 'ask' | 'conversation' | 'session' | 'seller' | 'listing' | 'media_kit' | 'playbook' | 'business_rules' | 'coverage' | 'distribution' | 'connection' | 'creative_engine' | 'creative_session' | 'campaign' | 'catalog' | 'event_source' | 'dimension' | 'property_list' | 'creative' | 'creative_format' | 'creative_asset' | 'creative_collection' | 'media_buy' | 'proposal' | 'audience' | 'rfp' | 'rfp_turn' | 'library_request' | 'account_relationship' | 'notification_config';
            object: {
                advertiserId?: string;
                sandbox?: boolean;
                /**
                 * AdCP TargetingOverlay (campaign subset); same shape as the save_campaign targetingOverlay input.
                 */
                targetingOverlay?: {
                    [key: string]: unknown;
                };
                [key: string]: unknown;
            };
            sourceId?: string;
            productQueryId?: string;
            products?: Array<unknown>;
            catalog?: unknown;
            accounts?: Array<unknown>;
            accountsTotal?: number;
            unavailableIncludes?: Array<unknown>;
            messages?: Array<unknown>;
            truncated?: boolean;
            [key: string]: unknown;
        };
        error: null;
    };
};

